preConditionHook:
// A run of body gaps: each of the last N bars is a bull trend bar (close above
// its own open) that ALSO opened above the prior bar's close. Brooks reads two
// or three of these on consecutive trend bars as urgency. This is the run form
// of the one-bar body-gap test; the body-to-body gap alone is its own rule.
//
// All-of-N, written the way ConsecutiveUpBars writes it -- start true and let
// any failing bar clear the flag -- so the loops run unconditionally and
// EasyLanguage's lack of short-circuiting cannot matter. Both flags are class
// members and persist across bars, so both are reset at the top of the hook.
allGapUp = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    if (el_le(open[kk], close[kk + 1])) allGapUp = false;
    if (el_le(close[kk], open[kk])) allGapUp = false;
}
allGapDown = true;
for (kk = 0; kk < (int)consecutiveBars; ++kk) {
    if (el_ge(open[kk], close[kk + 1])) allGapDown = false;
    if (el_ge(close[kk], open[kk])) allGapDown = false;
}
